require 'faye/websocket'
require 'eventmachine'
require 'json'
require 'securerandom'
require 'openssl'

module DistributedCache
  class WebSocketClient
    PROTOCOL_VERSION = "dcache-v2"
    HEARTBEAT_INTERVAL = 30
    RECONNECT_DELAY = 5

    attr_reader :node_id, :state, :pending_ops

    def initialize(config)
      @node_id = SecureRandom.uuid
      @config = config
      @state = :disconnected
      @pending_ops = {}
      @sequence = 0
      @mutex = Mutex.new
      @origin_validator = OriginValidator.new(config[:allowed_origins])
      @session_token = nil
      @authenticated = false
    end

    def connect(endpoint)
      @endpoint = endpoint
      EM.run do
        establish_connection
      end
    end

    private

    def establish_connection
      headers = build_connection_headers
      @ws = Faye::WebSocket::Client.new(
        @endpoint,
        [PROTOCOL_VERSION],
        headers: headers,
        tls: tls_options
      )

      @ws.on :open do |event|
        handle_open(event)
      end

      @ws.on :message do |event|
        handle_message(event)
      end

      @ws.on :close do |event|
        handle_close(event)
      end
    end

    def build_connection_headers
      {
        'X-Node-ID' => @node_id,
        'X-Protocol-Version' => PROTOCOL_VERSION,
        'X-Timestamp' => Time.now.to_i.to_s
      }
    end

    def tls_options
      {
        verify_peer: true,
        cert_chain_file: @config[:cert_file],
        private_key_file: @config[:key_file]
      }
    end

    def handle_open(event)
      @state = :connected
      initiate_handshake
    end

    def initiate_handshake
      challenge = SecureRandom.hex(32)
      @pending_challenge = challenge
      send_frame({
        type: 'auth_request',
        node_id: @node_id,
        challenge: challenge,
        capabilities: ['read', 'write', 'subscribe']
      })
    end

    def handle_message(event)
      frame = parse_frame(event.data)
      return unless frame

      case frame['type']
      when 'auth_response'
        process_auth_response(frame)
      when 'cache_response'
        process_cache_response(frame)
      when 'invalidation'
        process_invalidation(frame)
      when 'cluster_update'
        process_cluster_update(frame)
      end
    end

    def process_auth_response(frame)
      if verify_server_response(frame)
        @authenticated = true
        @session_token = frame['session_token']
        @state = :ready
        start_heartbeat
      else
        @ws.close(4001, 'Authentication failed')
      end
    end

    def verify_server_response(frame)
      return false unless frame['challenge_response']
      expected = compute_challenge_response(@pending_challenge, @config[:shared_secret])
      secure_compare(expected, frame['challenge_response'])
    end

    def compute_challenge_response(challenge, secret)
      OpenSSL::HMAC.hexdigest('SHA256', secret, challenge)
    end

    def secure_compare(a, b)
      return false unless a.bytesize == b.bytesize
      l = a.unpack("C#{a.bytesize}")
      r = b.unpack("C#{b.bytesize}")
      result = 0
      l.zip(r) { |x, y| result |= x ^ y }
      result == 0
    end

    def process_cache_response(frame)
      seq = frame['sequence']
      @mutex.synchronize do
        if callback = @pending_ops.delete(seq)
          callback.call(frame['value'], frame['error'])
        end
      end
    end

    def process_invalidation(frame)
      return unless @authenticated
      keys = frame['keys']
      return unless keys.is_a?(Array)
      keys.each { |k| local_cache_invalidate(k) }
    end

    def process_cluster_update(frame)
      return unless @authenticated
      if frame['origin_node'] && frame['origin_node'] != @node_id
        apply_cluster_topology(frame['topology'])
      end
    end

    def apply_cluster_topology(topology)
      return unless topology.is_a?(Hash)
      @cluster_nodes = topology['nodes'] || []
    end

    def cache_get(key, &callback)
      return unless @state == :ready
      seq = next_sequence
      @mutex.synchronize do
        @pending_ops[seq] = callback
      end
      send_frame({
        type: 'cache_get',
        key: key,
        sequence: seq,
        session_token: @session_token
      })
    end

    def cache_set(key, value, ttl: 3600, &callback)
      return unless @state == :ready
      seq = next_sequence
      @mutex.synchronize do
        @pending_ops[seq] = callback
      end
      send_frame({
        type: 'cache_set',
        key: key,
        value: value,
        ttl: ttl,
        sequence: seq,
        session_token: @session_token
      })
    end

    def send_frame(data)
      return unless @ws
      payload = JSON.generate(data)
      @ws.send(payload)
    end

    def parse_frame(raw)
      JSON.parse(raw)
    rescue JSON::ParserError
      nil
    end

    def next_sequence
      @mutex.synchronize { @sequence += 1 }
    end

    def start_heartbeat
      EM.add_periodic_timer(HEARTBEAT_INTERVAL) do
        send_frame({ type: 'heartbeat', node_id: @node_id, session_token: @session_token })
      end
    end

    def handle_close(event)
      @state = :disconnected
      @authenticated = false
      @session_token = nil
      schedule_reconnect
    end

    def schedule_reconnect
      EM.add_timer(RECONNECT_DELAY) { establish_connection }
    end

    def local_cache_invalidate(key)
      # Local LRU cache invalidation
    end
  end

  class OriginValidator
    def initialize(allowed_origins)
      @allowed_origins = Array(allowed_origins)
    end

    def valid?(origin)
      return true if @allowed_origins.empty?
      @allowed_origins.include?(origin)
    end
  end

  class ConnectionManager
    def initialize(config)
      @config = config
      @connections = {}
      @upgrade_validator = UpgradeValidator.new(config)
    end

    def handle_upgrade(env)
      return reject_upgrade(env) unless validate_upgrade_request(env)
      ws = Faye::WebSocket.new(env, [WebSocketClient::PROTOCOL_VERSION])
      setup_handlers(ws, env)
      ws.rack_response
    end

    def validate_upgrade_request(env)
      return false unless env['HTTP_UPGRADE']&.downcase == 'websocket'
      @upgrade_validator.validate(env)
    end

    def reject_upgrade(env)
      [403, {}, ['Forbidden']]
    end

    private

    def setup_handlers(ws, env)
      session = Session.new(ws, env)
      ws.on(:message) { |e| session.handle_message(e) }
      ws.on(:close) { |e| session.cleanup }
    end
  end

  class UpgradeValidator
    def initialize(config)
      @config = config
      @origin_validator = OriginValidator.new(config[:allowed_origins])
    end

    def validate(env)
      validate_protocol(env) &&
        validate_origin_header(env)
    end

    def validate_protocol(env)
      protocols = env['HTTP_SEC_WEBSOCKET_PROTOCOL']&.split(',')&.map(&:strip)
      return false unless protocols
      protocols.include?(WebSocketClient::PROTOCOL_VERSION)
    end

    def validate_origin_header(env)
      origin = env['HTTP_ORIGIN'] || env['HTTP_SEC_WEBSOCKET_ORIGIN']
      return false if origin.nil?
      @origin_validator.valid?(origin)
    end
  end

  class Session
    def initialize(ws, env)
      @ws = ws
      @env = env
      @authenticated = false
    end

    def handle_message(event)
      frame = JSON.parse(event.data) rescue nil
      return unless frame
      dispatch(frame)
    end

    def dispatch(frame)
      case frame['type']
      when 'auth_request'
        handle_auth(frame)
      else
        handle_operation(frame) if @authenticated
      end
    end

    def handle_auth(frame)
      # Server-side auth handling
    end

    def handle_operation(frame)
      # Process cache operations
    end

    def cleanup
      @authenticated = false
    end
  end
end
